import json
import re
from datetime import datetime, date

def clean_tutar(tutar):
    """Tutar alanını parse et"""
    if not isinstance(tutar, str):
        # Sayı ise string'e çevir
        tutar = str(tutar)

    # Para birimi simgeleri ve birim isimlerini çıkar
    tutar = tutar.replace('₺', '').replace('TL', '').strip()

    if not tutar:
        return None

    nokta_sayisi = tutar.count('.')
    virgul_sayisi = tutar.count(',')

    if nokta_sayisi == 0 and virgul_sayisi == 0:
        # Sadece rakam varsa direkt dön
        try:
            return float(tutar)
        except ValueError:
            return None

    # Virgül ve nokta hem varsa
    if nokta_sayisi > 0 and virgul_sayisi > 0:
        # Noktanın hemen arkasındaki rakam sayısını kontrol et
        nokta_kisa = tutar.rsplit('.', 1)[-1]
        if len(nokta_kisa) == 3 and nokta_kisa.isdigit():
            # Nokta binlik ayırıcı, virgül ondalık
            tutar = tutar.replace('.', '')  # Noktaları çıkar
            try:
                return float(tutar.replace(',', '.'))
            except ValueError:
                return None
        else:
            # Virgül ondalık ayırıcı, noktaları çıkar
            tutar = tutar.replace(',', '.')
            try:
                return float(tutar)
            except ValueError:
                return None

    # Sadece virgül varsa -> ondalık ayırıcı
    if virgul_sayisi > 0 and nokta_sayisi == 0:
        tutar = tutar.replace(',', '.')
        try:
            return float(tutar)
        except ValueError:
            return None

    # Sadece nokta varsa
    if nokta_sayisi > 0 and virgul_sayisi == 0:
        nokta_kisa = tutar.rsplit('.', 1)[-1]
        if len(nokta_kisa) == 3 and nokta_kisa.isdigit():
            # Nokta binlik ayırıcı
            tutar = tutar.replace('.', '')
            try:
                return float(tutar)
            except ValueError:
                return None
        else:
            # Nokta ondalık ayırıcı
            tutar = tutar.replace('.', ',')
            try:
                return float(tutar)
            except ValueError:
                return None

    return None


