    """Tarih stringini parse et ve geçerli tarihi dön"""
    if not isinstance(tarih_str, str):
        return None

    tarih_str = tarih_str.strip()

    # Türkçe ay isimleri dictionary
    ay_isimleri = {
        'ocak': 1, 'şubat': 2, 'mart': 3, 'nisan': 4, 'mayıs': 5, 'haziran': 6,
        'temmuz': 7, 'agustos': 8, 'eylul': 9, 'ekim': 10, 'kasım': 11, 'aralık': 12
    }

    # Format: YYYY-MM-DD
    if re.match(r'^\d{4}-\d{2}-\d{2}$', tarih_str):
        try:
            d = datetime.strptime(tarih_str, '%Y-%m-%d').date()
            return d
        except ValueError:
            pass

    # Format: YYYY/MM/DD
    if re.match(r'^\d{4}/\d{2}/\d{2}$', tarih_str):
        try:
            d = datetime.strptime(tarih_str, '%Y/%m/%d').date()
            return d
        except ValueError:
